package configs_test

import (
	"fmt"
	"testing"
	"time"

	"github.com/mbashem/cftracker/backend/configs"
)

// Generated by Codex and not thoroughly checked for correctness.
func TestLoadHTTPServerTimeouts(t *testing.T) {
	for _, setting := range []struct {
		key      configs.EnvKey
		fallback time.Duration
		read     func(configs.HTTPServerConfig) time.Duration
	}{
		{configs.HTTP_READ_HEADER_TIMEOUT, configs.DefaultHTTPReadHeaderTimeout, func(c configs.HTTPServerConfig) time.Duration { return c.ReadHeaderTimeout }},
		{configs.HTTP_READ_TIMEOUT, configs.DefaultHTTPReadTimeout, func(c configs.HTTPServerConfig) time.Duration { return c.ReadTimeout }},
		{configs.HTTP_WRITE_TIMEOUT, configs.DefaultHTTPWriteTimeout, func(c configs.HTTPServerConfig) time.Duration { return c.WriteTimeout }},
		{configs.HTTP_IDLE_TIMEOUT, configs.DefaultHTTPIdleTimeout, func(c configs.HTTPServerConfig) time.Duration { return c.IdleTimeout }},
		{configs.HTTP_SHUTDOWN_TIMEOUT, configs.DefaultHTTPShutdownTimeout, func(c configs.HTTPServerConfig) time.Duration { return c.ShutdownTimeout }},
	} {
		t.Run(string(setting.key), func(t *testing.T) {
			for _, testCase := range []struct {
				name, value, errorSuffix string
				want                     time.Duration
			}{
				{"empty setting uses default", "", "", setting.fallback},
				{"positive duration overrides default", "250ms", "", 250 * time.Millisecond},
				{"malformed duration is rejected", "slow", "must be a valid duration", setting.fallback},
				{"zero duration is rejected", "0s", "must be greater than zero", setting.fallback},
				{"negative duration is rejected", "-1s", "must be greater than zero", setting.fallback},
			} {
				t.Run(testCase.name, func(t *testing.T) {
					t.Chdir(t.TempDir())
					setConfigEnv(t, newConfigMockData())
					t.Setenv(string(setting.key), testCase.value)
					config, err := configs.Load()
					wantError := ""
					if testCase.errorSuffix != "" {
						wantError = fmt.Sprintf("%s %s", setting.key, testCase.errorSuffix)
					}
					assertErrorText(t, err, wantError)
					if actual := setting.read(config.HTTPServer); actual != testCase.want {
						t.Fatalf("timeout=%s, want %s", actual, testCase.want)
					}
				})
			}
		})
	}
}
